 "content": "def transform(grid):
    """Render each marker's demonstrated fixed ray; 2/3/6 crossings spawn 4."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rays = {}
    origins = {}

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # An L-shaped projection: two east, then one north, ending in 1.
                path = [(r, c + 1, 5), (r, c + 2, 5), (r - 1, c + 2, 1)]
                for rr, cc, value in path:
                    if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                        out[rr][cc] = value
            elif color == 2:
                # Four-cell horizontal ray to the left, with a 2 at its endpoint.
                path = [(r, c - k, 2 if k == 4 else 5) for k in range(1, 5)]
                rays.setdefault(2, set()).update((rr, cc) for rr, cc, _ in path if 0 <= rr < h and 0 <= cc < w)
                origins[(r, c)] = path
            elif color == 3:
                # Three-cell vertical ray downward.
                path = [(r + k, c, 3 if k == 3 else 5) for k in range(1, 4)]
                rays.setdefault(3, set()).update((rr, cc) for rr, cc, _ in path if 0 <= rr < h and 0 <= cc < w)
                origins[(r, c)] = path
            elif color == 6:
                # Six-cell vertical ray upward.
                path = [(r - k, c, 6 if k == 6 else 5) for k in range(1, 7)]
                rays.setdefault(6, set()).update((rr, cc) for rr, cc, _ in path if 0 <= rr < h and 0 <= cc < w)
                origins[(r, c)] = path

    # Paint rays, retaining an explicit record of their path cells.
    for (r, c), path in origins.items():
        for rr, cc, value in path:
            if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                out[rr][cc] = value

    # A crossing between the horizontal 2-ray and vertical 3/6-ray becomes
    # a 4, which projects diagonally down-left to the grid edge.
    crossings = (rays.get(2, set()) & (rays.get(3, set()) | rays.get(6, set())))
    for r, c in crossings:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == 0 or out[rr][cc] == 5:
                out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
