    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rays = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Right twice, then turn north; the final cell is 1.
                path = [(r, c + 1), (r, c + 2), (r - 1, c + 2)]
                for i, (rr, cc) in enumerate(path):
                    if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                        out[rr][cc] = 1 if i == 2 else 5
            elif color in (2, 3, 6):
                if color == 2:
                    dr, dc, length = 0, -1, 4
                elif color == 3:
                    dr, dc, length = 1, 0, 3
                else:  # 6
                    dr, dc, length = -1, 0, 6
                path = [(r + dr * k, c + dc * k) for k in range(1, length + 1)]
                # Paint intermediate 5s and same-color endpoint; retain paths
                # so crossings can be detected independent of scan order.
                for k, (rr, cc) in enumerate(path, start=1):
                    if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                        out[rr][cc] = color if k == length else 5
                rays.append((color, set((rr, cc) for rr, cc in path if 0 <= rr < h and 0 <= cc < w)))

    horizontal = set().union(*(cells for color, cells in rays if color == 2)) if any(color == 2 for color, _ in rays) else set()
    vertical = set().union(*(cells for color, cells in rays if color in (3, 6))) if any(color in (3, 6) for color, _ in rays) else set()
    crossings = horizontal & vertical
    for r, c in crossings:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] in (0, 5):
                out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
